const lines = require('fs').readFileSync(0, 'utf8').split('\n');
const first = lines[0].split(' ');
const N = parseInt(first[0]);
const F = parseInt(first[1]);
const grid = [];
for (let i = 1; i <= N; i++) grid.push(lines[i].split(''));

if (parseInt(grid[0][0]) <= F) {
  const visited = Array.from({length: N}, () => new Array(N).fill(false));
  const queue = [[0, 0]];
  visited[0][0] = true;
  grid[0][0] = '*';
  while (queue.length) {
    const [r, c] = queue.shift();
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < N && nc >= 0 && nc < N && !visited[nr][nc] && parseInt(grid[nr][nc]) <= F) {
        visited[nr][nc] = true;
        grid[nr][nc] = '*';
        queue.push([nr, nc]);
      }
    }
  }
}

let out = '';
for (let i = 0; i < N; i++) out += grid[i].join('') + '\n';
process.stdout.write(out);
